              "period": 1,
              "periodUnit": "d"
            }
          },
          "doseAndRate": [
            {
              "doseQuantity": {
                "value": 1,
                "unit": "g"
              }
            }
          ],
          "maxDosePerPeriod": {
            "numerator": {
              "value": 4,
              "unit": "g"
            },
            "denominator": {
              "value": 1,
              "unit": "day"
            }
          }
        }
      ]
    }
  ]
